// Extract all images from FormData
const items = [];
const binaryData = $input.all();

let imageCount = 0;
const images = [];

for (const item of binaryData) {
  if (item.binary) {
    for (const [key, value] of Object.entries(item.binary)) {
      if (key.startsWith('image')) {
        images.push({
          binary: { image: value },
          json: {
            imageIndex: imageCount,
            imageName: value.fileName || `image_${imageCount}.jpg`,
            mimeType: value.mimeType || 'image/jpeg',
            fileSize: value.fileSize || 0
          }
        });
        imageCount++;
      }
    }
  }
}

if (imageCount === 0) {
  throw new Error('No images found in request');
}

if (imageCount > 5) {
  throw new Error('Maximum 5 images allowed');
}

console.log(`Processing ${imageCount} images`);
return images;

// Parse each Gemini response
let imageIndex = 0;
const items = [];

for (const item of $input.all()) {
  try {
    let extractedText = '';
    const data = item.json;

    // Extract text from Gemini (same as current workflow)
    if (Array.isArray(data) && data.length > 0) {
      const firstItem = data[0];
      if (firstItem.content?.parts?.[0]?.text) {
        extractedText = firstItem.content.parts[0].text;
      }
    } else if (data.content?.parts?.[0]?.text) {
      extractedText = data.content.parts[0].text;
    } else if (typeof data.response === 'string') {
      extractedText = data.response;
    } else if (typeof data.text === 'string') {
      extractedText = data.text;
    }

    if (!extractedText) {
      throw new Error('No response from Gemini API');
    }

    extractedText = extractedText
      .replace(/```json\n?/gi, '')
      .replace(/```\n?/g, '')
      .trim();

    const productData = JSON.parse(extractedText);

    // Add metadata using loop counter
    productData._imageIndex = imageIndex;
    productData._imageName = item.binary?.image?.fileName || `image_${imageIndex}.jpg`;
    productData._extractionSuccess = true;

    items.push({ json: productData, binary: item.binary });

  } catch (err) {
    console.error(`Image ${imageIndex} failed:`, err.message);

    items.push({
      json: {
        _imageIndex: imageIndex,
        _imageName: item.binary?.image?.fileName || `image_${imageIndex}.jpg`,
        _extractionSuccess: false,
        _error: err.message
      }
    });
  }

  imageIndex++;
}

return items;

// Merge all results using intelligent strategy
const allResults = $input.all();

console.log(`Merging ${allResults.length} image results...`);

// Separate successful and failed extractions
const successfulResults = allResults.filter(item => item.json._extractionSuccess === true);
const failedResults = allResults.filter(item => item.json._extractionSuccess === false);

console.log(`Successful: ${successfulResults.length}, Failed: ${failedResults.length}`);

if (successfulResults.length === 0) {
  throw new Error('All images failed to extract data');
}

// Helper: Select longest string
function selectLongest(values) {
  const validValues = values.filter(v => v && typeof v === 'string' && v.trim() !== '');
  if (validValues.length === 0) return '';
  return validValues.reduce((longest, current) => 
    current.length > longest.length ? current : longest
  );
}

// Helper: Select most frequent value
function selectMostFrequent(values) {
  const validValues = values.filter(v => v && typeof v === 'string' && v.trim() !== '');
  if (validValues.length === 0) return '';

  const frequency = {};
  validValues.forEach(v => {
    frequency[v] = (frequency[v] || 0) + 1;
  });

  return Object.keys(frequency).reduce((a, b) => 
    frequency[a] > frequency[b] ? a : b
  );
}

// Helper: Select earliest date (most conservative for expiry)
function selectEarliest(dates) {
  const validDates = dates
    .filter(d => d && typeof d === 'string' && d.trim() !== '')
    .map(d => new Date(d))
    .filter(d => !isNaN(d.getTime()));

  if (validDates.length === 0) return null;

  const earliest = validDates.reduce((min, current) => 
    current < min ? current : min
  );

  return earliest.toISOString().split('T')[0];
}

// Helper: Select highest price
function selectHighestPrice(prices) {
  const validPrices = prices.filter(p => p && typeof p === 'string' && p.trim() !== '');
  if (validPrices.length === 0) return 'N/A';

  // Extract numeric value for comparison
  const pricesWithValues = validPrices.map(p => {
    const match = p.match(/([\d.]+)/);
    return {
      original: p,
      value: match ? parseFloat(match[1]) : 0
    };
  });

  return pricesWithValues.reduce((max, current) => 
    current.value > max.value ? current : max
  ).original;
}

// Helper: Merge ingredients (deduplicate)
function mergeIngredients(ingredientLists) {
  const allIngredients = new Set();

  ingredientLists.forEach(list => {
    if (list && typeof list === 'string') {
      const ingredients = list.split(',').map(i => i.trim().toLowerCase());
      ingredients.forEach(i => {
        if (i) allIngredients.add(i);
      });
    }
  });

  return Array.from(allIngredients).join(', ');
}

// Helper: Merge nutrition (average non-null values)
function mergeNutrition(nutritionObjects) {
  const merged = {};
  const keys = ['energyKcal', 'proteinG', 'carbsG', 'sugarG', 'fatG', 'saturatedFatG', 'transFatG', 'sodiumMg', 'fiberG'];

  keys.forEach(key => {
    const validValues = nutritionObjects
      .map(n => n[key])
      .filter(v => v != null && typeof v === 'number' && !isNaN(v));

    if (validValues.length > 0) {
      const sum = validValues.reduce((a, b) => a + b, 0);
      merged[key] = Math.round((sum / validValues.length) * 10) / 10;
    } else {
      merged[key] = null;
    }
  });

  return merged;
}

// Helper: Calculate confidence based on field agreement
function calculateConfidence(results, mergedProduct) {
  let agreementScore = 0;
  const totalFields = 9; // Number of key fields to check

  // Check agreement for each field
  const productNames = results.map(r => r.productName);
  const uniqueProductNames = new Set(productNames.filter(p => p));
  if (uniqueProductNames.size === 1) agreementScore += 1;

  const brands = results.map(r => r.brand);
  const uniqueBrands = new Set(brands.filter(b => b));
  if (uniqueBrands.size === 1) agreementScore += 1;

  const categories = results.map(r => r.category);
  const uniqueCategories = new Set(categories.filter(c => c));
  if (uniqueCategories.size === 1) agreementScore += 1;

  const subCategories = results.map(r => r.subCategory);
  const uniqueSubCategories = new Set(subCategories.filter(s => s));
  if (uniqueSubCategories.size === 1) agreementScore += 1;

  const expiryDates = results.map(r => r.expiryDate);
  const uniqueExpiryDates = new Set(expiryDates.filter(e => e));
  if (uniqueExpiryDates.size === 1) agreementScore += 1;

  const mrps = results.map(r => r.mrp);
  const uniqueMrps = new Set(mrps.filter(m => m));
  if (uniqueMrps.size === 1) agreementScore += 1;

  const weights = results.map(r => r.weight);
  const uniqueWeights = new Set(weights.filter(w => w));
  if (uniqueWeights.size === 1) agreementScore += 1;

  // Ingredients - check if at least 70% overlap
  const ingredientSets = results.map(r => {
    if (!r.ingredients) return new Set();
    return new Set(r.ingredients.toLowerCase().split(',').map(i => i.trim()));
  }).filter(s => s.size > 0);

  if (ingredientSets.length > 1) {
    const intersection = ingredientSets.reduce((acc, curr) => {
      return new Set([...acc].filter(x => curr.has(x)));
    });
    const union = ingredientSets.reduce((acc, curr) => {
      return new Set([...acc, ...curr]);
    });
    const overlap = intersection.size / union.size;
    if (overlap >= 0.7) agreementScore += 1;
  } else if (ingredientSets.length === 1) {
    agreementScore += 1;
  }

  // Nutrition - check if values are within 20% of each other
  const nutritionObjects = results.map(r => r.nutrition).filter(n => n);
  if (nutritionObjects.length > 1) {
    const keys = ['energyKcal', 'proteinG', 'carbsG', 'sugarG', 'fatG'];
    let nutritionAgreement = 0;
    let nutritionChecks = 0;

    keys.forEach(key => {
      const values = nutritionObjects.map(n => n[key]).filter(v => v != null && !isNaN(v));
      if (values.length > 1) {
        nutritionChecks++;
        const avg = values.reduce((a, b) => a + b, 0) / values.length;
        const allWithin20Percent = values.every(v => Math.abs(v - avg) / avg <= 0.2);
        if (allWithin20Percent) nutritionAgreement++;
      }
    });

    if (nutritionChecks > 0 && nutritionAgreement / nutritionChecks >= 0.8) {
      agreementScore += 1;
    }
  } else if (nutritionObjects.length === 1) {
    agreementScore += 1;
  }

  return Math.round((agreementScore / totalFields) * 100);
}

// Extract data from successful results
const results = successfulResults.map(item => item.json);

// Apply merging strategies
const mergedProduct = {
  productName: selectLongest(results.map(r => r.productName)),
  brand: selectLongest(results.map(r => r.brand)),
  category: selectMostFrequent(results.map(r => r.category)),
  subCategory: selectMostFrequent(results.map(r => r.subCategory)),
  expiryDate: selectEarliest(results.map(r => r.expiryDate)),
  mrp: selectHighestPrice(results.map(r => r.mrp)),
  weight: selectMostFrequent(results.map(r => r.weight)),
  ingredients: mergeIngredients(results.map(r => r.ingredients)),
  nutrition: mergeNutrition(results.map(r => r.nutrition || {})),
  quantity: 1,
  extractedAt: new Date().toISOString()
};

// Calculate confidence
const confidence = calculateConfidence(results, mergedProduct);

// Add metadata
mergedProduct._metadata = {
  imagesProcessed: successfulResults.length,
  totalImages: allResults.length,
  failedImages: failedResults.length,
  failedImageNames: failedResults.map(r => r.json._imageName),
  confidence: confidence
};

console.log('Merged product:', JSON.stringify(mergedProduct, null, 2));
console.log('Confidence:', confidence + '%');

return [{ json: mergedProduct }];

// Calculate days to expire in human-readable format
const items = [];

for (const item of $input.all()) {
  const data = item.json;

  // Parse expiry date
  if (!data.expiryDate) {
    items.push({
      json: {
        ...data,
        daysToExpire: 'Unknown',
        expiryStatus: 'Unknown',
        daysToExpireRaw: null
      },
      pairedItem: { item: 0 }
    });
    continue;
  }

  const expiryDate = new Date(data.expiryDate);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  expiryDate.setHours(0, 0, 0, 0);

  const diffTime = expiryDate - today;
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  let humanReadable = '';
  let status = '';

  if (diffDays < 0) {
    humanReadable = `Expired ${Math.abs(diffDays)} days ago`;
    status = 'Expired';
  } else if (diffDays === 0) {
    humanReadable = 'Expires today';
    status = 'Critical';
  } else if (diffDays === 1) {
    humanReadable = 'Expires tomorrow';
    status = 'Critical';
  } else if (diffDays <= 7) {
    humanReadable = `${diffDays} days`;
    status = 'Warning';
  } else if (diffDays <= 14) {
    const weeks = Math.floor(diffDays / 7);
    const days = diffDays % 7;
    if (days === 0) {
      humanReadable = `${weeks} week${weeks > 1 ? 's' : ''}`;
    } else {
      humanReadable = `${weeks} week${weeks > 1 ? 's' : ''} ${days} day${days > 1 ? 's' : ''}`;
    }
    status = 'Good';
  } else if (diffDays <= 30) {
    humanReadable = `${diffDays} days`;
    status = 'Good';
  } else {
    const months = Math.floor(diffDays / 30);
    const remainingDays = diffDays % 30;
    if (remainingDays === 0) {
      humanReadable = `${months} month${months > 1 ? 's' : ''}`;
    } else if (remainingDays <= 7) {
      humanReadable = `${months} month${months > 1 ? 's' : ''} ${remainingDays} day${remainingDays > 1 ? 's' : ''}`;
    } else {
      const weeks = Math.floor(remainingDays / 7);
      humanReadable = `${months} month${months > 1 ? 's' : ''} ${weeks} week${weeks > 1 ? 's' : ''}`;
    }
    status = 'Good';
  }

  items.push({
    json: {
      ...data,
      daysToExpire: humanReadable,
      expiryStatus: status,
      daysToExpireRaw: diffDays
    },
    pairedItem: { item: 0 }
  });
}

return items;

// Analyze health rating based on ingredients and nutrition
const items = [];

for (const item of $input.all()) {
  const data = item.json;

  const ingredients = (data.ingredients || '').toLowerCase();
  const nutrition = data.nutrition || {};

  let score = 100; // Start with perfect score
  const concerns = [];

  // Check for harmful ingredients
  const harmfulIngredients = [
    { name: 'Contains trans fats which increase bad cholesterol and heart disease risk', penalty: 40, pattern: /trans.?fat|partially hydrogenated|hydrogenated oil/ },
    { name: 'Contains high fructose corn syrup linked to obesity and diabetes', penalty: 25, pattern: /high.?fructose.?corn.?syrup|hfcs/ },
    { name: 'Contains artificial sweeteners which may affect metabolism and gut health', penalty: 20, pattern: /aspartame|sucralose|saccharin|acesulfame/ },
    { name: 'Contains MSG (flavor enhancer) which may cause sensitivity in some people', penalty: 15, pattern: /monosodium.?glutamate|msg|e621/ },
    { name: 'Contains sodium nitrite (preservative) linked to cancer risk when consumed regularly', penalty: 20, pattern: /sodium.?nitrite|e250/ },
    { name: 'Contains artificial colors which may cause hyperactivity in children', penalty: 15, pattern: /tartrazine|e102|e110|e129|sunset yellow|red 40/ },
    { name: 'Contains palm oil which is high in saturated fat', penalty: 10, pattern: /palm.?oil/ },
    { name: 'Contains multiple preservatives which may have cumulative health effects', penalty: 10, pattern: /(e2\d{2}|preservative).*?(e2\d{2}|preservative)/ }
  ];

  harmfulIngredients.forEach(item => {
    if (item.pattern.test(ingredients)) {
      score -= item.penalty;
      concerns.push(item.name);
    }
  });

  // Check nutritional values (per 100g/100ml) - handle null values
  if (nutrition.sugarG != null && nutrition.sugarG > 15) {
    score -= 15;
    concerns.push(`High sugar content (${nutrition.sugarG}g per 100g) - linked to weight gain and diabetes`);
  }

  if (nutrition.sodiumMg != null && nutrition.sodiumMg > 500) {
    score -= 15;
    concerns.push(`High sodium content (${nutrition.sodiumMg}mg per 100g) - may increase blood pressure`);
  }

  if (nutrition.saturatedFatG != null && nutrition.saturatedFatG > 5) {
    score -= 15;
    concerns.push(`High saturated fat (${nutrition.saturatedFatG}g per 100g) - raises cholesterol levels`);
  }

  if (nutrition.transFatG != null && nutrition.transFatG > 0) {
    score -= 30;
    concerns.push(`Contains trans fat (${nutrition.transFatG}g per 100g) - extremely harmful to heart health`);
  }

  // Positive factors - handle null values
  if (nutrition.fiberG != null && nutrition.fiberG >= 5) {
    score += 5;
  }

  if (nutrition.proteinG != null && nutrition.proteinG >= 10) {
    score += 5;
  }

  // Ensure score is between 0-100
  score = Math.max(0, Math.min(100, score));

  // Cap score at 99.9 for database NUMERIC(3,1) constraint
  score = Math.min(99.9, score);

  // Determine rating
  let rating = '';
  if (score >= 80) {
    rating = 'Healthy';
  } else if (score >= 60) {
    rating = 'Moderate';
  } else if (score >= 40) {
    rating = 'Not Healthy';
  } else {
    rating = 'Harmful';
  }

  items.push({
    json: {
      ...data,
      healthRating: rating,
      healthScore: score,
      concerns: concerns
    },
    pairedItem: { item: 0 }
  });
}

return items;
